// Deterministic global sum over `count` elements into *result (both live in
// device memory). Two-stage: a fixed grid of work-items computes ordered
// partial sums over contiguous chunks into tmp (needs >= 256 floats), then a
// single work-item accumulates the partials in order. Chunk boundaries depend
// only on `count`, so the result is bit-deterministic run to run.
// Fire-and-forget on the in-order queue; use a blocking copy to read *result.
template<class Float>
inline void global_sum_deterministic(float* result, const Float* values, size_t count, sycl::queue& q, float* tmp) {
    constexpr int P = 256;
    if (count == 0) {
        q.memset(result, 0, sizeof(float));
        return;
    }
    int p = (count < (size_t)P) ? (int)count : P;
    size_t chunk = (count + (size_t)p - 1) / (size_t)p;
    q.parallel_for(sycl::range<1>((size_t)p), [=](sycl::id<1> id) {
        size_t s = id[0] * chunk;
        size_t e = s + chunk;
        if (e > count) { e = count; }
        float acc = 0.0f;
        for (size_t i = s; i < e; i++) {
            acc += (float)values[i];
        }
        tmp[id[0]] = acc;
    });
    q.parallel_for(sycl::range<1>(1), [=](sycl::id<1>) {
        float total = 0.0f;
        for (int i = 0; i < p; i++) { total += tmp[i]; }
        *result = total;
    });
}

