    int g = (count < (size_t)GMAX) ? (int)count : GMAX;
    size_t chunk = (count + (size_t)g - 1) / (size_t)g;
    float* partials = tmp; // num_slices * g floats of device scratch
    // Flat 1-D grid over (slice, chunk) pairs (friendlier to some backends
    // than a 2-D range with a size-1 dimension); identical chunk assignment
    // and accumulation order, so results are unchanged.
    size_t total = (size_t)num_slices * (size_t)g;
    q.parallel_for(sycl::range<1>(total), [=](sycl::id<1> id) {
        size_t s = id[0] / (size_t)g;
        size_t j = id[0] % (size_t)g;
        const T* v = values + (ptrdiff_t)s * stride;
        size_t b = j * chunk;
        size_t e = b + chunk;
        if (e > count) { e = count; }
        float acc0 = 0.0f, acc1 = 0.0f, acc2 = 0.0f, acc3 = 0.0f;
        size_t i = b;
        size_t e4 = b + (e - b) / 4 * 4;
        for (; i < e4; i += 4) {
            float x0 = (float)v[i], x1 = (float)v[i+1], x2 = (float)v[i+2], x3 = (float)v[i+3];
            acc0 += x0 * x0; acc1 += x1 * x1; acc2 += x2 * x2; acc3 += x3 * x3;
        }
        float acc = (acc0 + acc1) + (acc2 + acc3);
        for (; i < e; i++) {
            float x = (float)v[i];
            acc += x * x;
        }
        partials[s * (size_t)g + j] = acc;
    });
    q.parallel_for(sycl::range<1>((size_t)num_slices), [=](sycl::id<1> id) {
        size_t s = id[0];
        double acc = (double)out[s];
        for (int j = 0; j < g; j++) { acc += (double)partials[s * (size_t)g + j]; }
        out[s] = (float)acc;
    });
}

