        gelu_forward(out, pre_gelu, (size_t)B*T*OC, q);
    } else {

        matmul_onemath(out, weight, inp, bias, OC, B*T, C, q, tmp_fp32, false, pre_gelu, false, pre_gelu);
    }
}

