/*
Portable strided-batched GEMM helpers (SYCL 2020 + oneMath only).

Dense GEMMs use oneMath bf16 -> fp32 gemm plus a separate convert epilogue.
Batched attention GEMMs use oneMath half -> fp32 strided batch: bf16 inputs
are converted once to half staging, then a single batched launch covers all
(batch, head) pairs with fp32 accumulation. Callers fuse the fp32 -> bf16
convert into their consumer (softmax / unpermute / permute), so no extra
round trip is introduced beyond the staging converts.

Single code path for every shape and every device: no size, shape or device
queries here. Small shapes and large shapes run exactly the same kernels.
*/
#ifndef SYCL_BATCHED_GEMM_H
#define SYCL_BATCHED_GEMM_H

#include <stdint.h>
#include <oneapi/math/blas.hpp>
// llmc internal imports
#include "sycl_common.h"

// bf16 -> half staging convert, one work-item per element.
inline void bf16_to_half_convert(sycl::half* dst, const floatX* src, size_t n, sycl::queue& q) {
    if (n == 0) { return; }
    q.parallel_for(sycl::range<1>(n), [=](sycl::id<1> id) {
        size_t i = id[0];
        dst[i] = (sycl::half)(float)src[i];
    });
}

// Strided-batched half -> fp32 GEMM with the same row-major convention used
// everywhere in this port: for each batch b,
//   Out(m x n) = op_row(A)(m x k) * op_row(B)(k x n),
// fp32 accumulation into tmp (batch-major, m*n floats per batch).
// Implemented as one oneMath strided batch launch over all batches:
//   C_col(n x m) = U(n x k) * V(k x m), U sourced from B, V sourced from A.
// A row-major (a x b) aliases a column-major (b x a) with leading dim b.
inline void half_strided_batched_gemm(float* tmp,
                     const sycl::half* A, const sycl::half* B,
                     int m, int n, int k, bool transA, bool transB,
                     size_t strideA, size_t strideB, int batch_count,
                     sycl::queue& q) {
    if (batch_count <= 0 || m <= 0 || n <= 0 || k <= 0) { return; }
    using namespace oneapi::math;
    transpose tu = transB ? transpose::trans : transpose::nontrans;
    transpose tv = transA ? transpose::trans : transpose::nontrans;
    int64_t ldu = transB ? (int64_t)k : (int64_t)n;
    int64_t ldv = transA ? (int64_t)m : (int64_t)k;
    int64_t ldc = (int64_t)n;
    int64_t strideU = (int64_t)strideB;
    int64_t strideV = (int64_t)strideA;
    int64_t strideC = (int64_t)m * n;
    blas::column_major::gemm_batch(q, tu, tv,
        (int64_t)n, (int64_t)m, (int64_t)k,
        1.0f, B, ldu, strideU, A, ldv, strideV,
        0.0f, tmp, ldc, strideC, (int64_t)batch_count);
}

#endif

