            sycl::local_accessor<float, 2> As(sycl::range<2>(32, 33), h);
            sycl::local_accessor<float, 2> Bs(sycl::range<2>(32, 33), h);
            h.parallel_for(sycl::nd_range<1>(groups * WG, WG), [=](sycl::nd_item<1> it) {
