        sycl::half* ha = nullptr;
        sycl::half* hb = nullptr;
        size_t na = 0;
        size_t nb = 0;
    };
    static BatchedStage st;
    // (Re)allocation is host-synchronous by construction: sizes only depend
    // on shapes, and every caller passes the same training shapes after the
    // first call; the test's small shapes allocate once up front as well.
    auto ensure = [&](sycl::half*& p, size_t& cur, size_t need) {
        if (cur < need) {
            if (p) { sycl::free(p, q); p = nullptr; cur = 0; }
            p = sycl::malloc_device<sycl::half>(need, q);
            cur = p ? need : 0;
        }
    };
    // NOTE: allocation below blocks the queue on growth only; steady state
    // never allocates.
    ensure(st.ha, st.na, a_elems);
    ensure(st.hb, st.nb, b_elems);
    bf16_to_half_convert(st.ha, A, a_elems, q);
    bf16_to_half_convert(st.hb, B, b_elems, q);
    half_strided_batched_gemm(tmp_fp32, st.ha, st.hb, m, n, k, transA, transB,
                              strideA, strideB, batch_count, q);
    (void)c_elems;
    return 2;
}

