#include <cstdio>
#include <vector>
#include <random>
int main(){
  sycl::queue q;
  using namespace oneapi::math;
  // emulate attention qk GEMM: m=n=64,k=64 random bf16, compare bf16-gemm vs half-staged-batched
  constexpr int64_t m=64,n=64,k=64,batch=8;
  std::mt19937 rng(0); std::normal_distribution<float> d(0,1);
  std::vector<oneapi::math::bfloat16> hA(m*k*batch), hB(k*n*batch);
  for (auto& x : hA) x = oneapi::math::bfloat16(d(rng));
  for (auto& x : hB) x = oneapi::math::bfloat16(d(rng));
  oneapi::math::bfloat16* A = sycl::malloc_device<oneapi::math::bfloat16>(m*k*batch, q);
  oneapi::math::bfloat16* B = sycl::malloc_device<oneapi::math::bfloat16>(k*n*batch, q);
  q.memcpy(A, hA.data(), m*k*batch*sizeof(oneapi::math::bfloat16)).wait();
  q.memcpy(B, hB.data(), k*n*batch*sizeof(oneapi::math::bfloat16)).wait();
  // route 1: loop of bf16 gemms (reference = old code path)
  float* Cref = sycl::malloc_device<float>(m*n*batch, q);
  for (int b=0;b<batch;b++)
    blas::column_major::gemm(q, transpose::nontrans, transpose::nontrans, n, m, k, 1.0f,
      B+b*k*n, n, A+b*m*k, k, 0.0f, Cref+b*m*n, n).wait();
  // route 2: half staged strided batch
  sycl::half* hA2 = sycl::malloc_device<sycl::half>(m*k*batch, q);
  sycl::half* hB2 = sycl::malloc_device<sycl::half>(k*n*batch, q);
  float* C2 = sycl::malloc_device<float>(m*n*batch, q);
  q.parallel_for(sycl::range<1>(m*k*batch), [=](sycl::id<1> id){ hA2[id[0]] = (sycl::half)(float)A[id[0]]; }).wait();
  q.parallel_for(sycl::range<1>(k*n*batch), [=](sycl::id<1> id){ hB2[id[0]] = (sycl::half)(float)B[id[0]]; }).wait();
  blas::column_major::gemm_batch(q, transpose::nontrans, transpose::nontrans, n, m, k, 1.0f,
    hB2, n, k*n, hA2, k, m*k, 0.0f, C2, n, m*n, batch).wait();
  std::vector<float> r(m*n*batch), c(m*n*batch);
  q.memcpy(r.data(), Cref, m*n*batch*sizeof(float)).wait();
  q.memcpy(c.data(), C2, m*n*batch*sizeof(float)).wait();
  double mx=0; for (size_t i=0;i<r.size();i++) mx = std::max(mx, (double)std::abs(r[i]-c[i]));
  printf("maxdiff bf16loop vs halfbatch = %e\n", mx);
}
