  q.parallel_for(sycl::range<1>(NB*T*HS), [=](sycl::id<1> id){ Qh[id[0]] = (sycl::half)(float)Q[id[0]]; }).wait();
  q.parallel_for(sycl::range<1>(NB*T*HS), [=](sycl::id<1> id){ Kh[id[0]] = (sycl::half)(float)K[id[0]]; }).wait();
  blas::column_major::gemm_batch(q, transpose::trans, transpose::nontrans, T, T, HS, 1.0f,
    Kh, HS, T*HS, Qh, HS, T*HS, 0.0f, C2, T, T*T, NB).wait();
  std::vector<float> r(NB*T*T), c(NB*T*T);
