#include <sycl/sycl.hpp>
#include <oneapi/math/blas.hpp>
#include <cstdio>
#include <vector>
#include <random>
// replicate the OLD tiled kernel accumulation (sequential k, fp32 from bf16) vs oneMath bf16 gemm on CPU
int main(){
  sycl::queue q;
  using namespace oneapi::math;
  constexpr int m=64,n=64,k=64;
  std::mt19937 rng(2); std::normal_distribution<float> d(0,1);
  std::vector<oneapi::math::bfloat16> hA(m*k), hB(k*n);
  for (auto& x : hA) x = oneapi::math::bfloat16(d(rng));
  for (auto& x : hB) x = oneapi::math::bfloat16(d(rng));
  // tiled reference on host: C= A*B row-major, sequential k accumulation in fp32
  std::vector<float> Ct(m*n, 0);
