  oneapi::math::bfloat16* W = sycl::malloc_device<oneapi::math::bfloat16>(OC*C_, q);
  oneapi::math::bfloat16* In = sycl::malloc_device<oneapi::math::bfloat16>(BT*C_, q);
  float* O = sycl::malloc_device<float>(OC*BT, q);
