#include <sycl/sycl.hpp>
#include <oneapi/math/blas.hpp>
#include <cstdio>
#include <vector>
#include <random>
int main(){
  sycl::queue q;
  using namespace oneapi::math;
  // batched mapping check: preatt Out(TxT)=Q(TxHS)*K^T. Code calls:
  // half_strided_batched_gemm(tmp, ha, hb, m=T,n=T,k=HS, transA=false, transB=true, strideA=T*HS, strideB=T*HS, batch)
  //  -> gemm_batch(tu=trans,tv=nontrans, n=T,m=T,k=HS, B=hb,ldu=k=HS, A=ha,ldv=k=HS, C,ldc=n=T)
  // So col C(n x m)=(T x T) = U*B... U=op(Bb)=trans(Bb): Bb is col (n x k)=(T x HS)?? Bb points to row-major (T x HS) = col (HS x T). trans => (T x HS). V=op(Ab)=nontrans(Ab): Ab row-major (T x HS)=col(HS x T) => (HS x T)?? dims (HS x T) but need (k x m)=(HS x T). OK.
  // C = U*V = (T x HS)*(HS x T) = (T x T). Correct.
  // Host reference row-major: Out[i,j] = sum_l Q[i,l]*K[j,l].
  constexpr int T=64,HS=64,NB=4;
  std::mt19937 rng(5); std::normal_distribution<float> d(0,1);
  std::vector<oneapi::math::bfloat16> hQ(NB*T*HS), hK(NB*T*HS);
  for (auto& x : hQ) x = oneapi::math::bfloat16(d(rng));
  for (auto& x : hK) x = oneapi::math::bfloat16(d(rng));
  std::vector<float> Ct(NB*T*T, 0);
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++) for (int j=0;j<T;j++){ float a=0; for(int l=0;l<HS;l++) a+=(float)hQ[b*T*HS+i*HS+l]*(float)hK[b*T*HS+j*HS+l]; Ct[b*T*T+i*T+j]=a; }
  sycl::half* Qh = sycl::malloc_device<sycl::half>(NB*T*HS, q);
  sycl::half* Kh = sycl::malloc_device<sycl::half>(NB*T*HS, q);
  float* O = sycl::malloc_device<float>(NB*T*T, q);
  std::vector<sycl::half> qh(NB*T*HS), kh(NB*T*HS);
  for (size_t i=0;i<qh.size();i++){ qh[i]=(sycl::half)(float)hQ[i]; kh[i]=(sycl::half)(float)hK[i]; }
  q.memcpy(Qh, qh.data(), NB*T*HS*sizeof(sycl::half)).wait();
  q.memcpy(Kh, kh.data(), NB*T*HS*sizeof(sycl::half)).wait();
  q.memset(O, 0, NB*T*T*sizeof(float)).wait();
  blas::column_major::gemm_batch(q, transpose::trans, transpose::nontrans, T, T, HS, 1.0f,
    Kh, HS, (int64_t)T*HS, Qh, HS, (int64_t)T*HS, 0.0f, O, T, (int64_t)T*T, NB).wait();
  std::vector<float> Co(NB*T*T);
  q.memcpy(Co.data(), O, NB*T*T*sizeof(float)).wait();
  // col C(T x T) batch b: element (i,j) at Co[b*T*T + j*T+i] == row Ct[b*T*T+i*T+j]
  double mx=0; for (int b=0;b<NB;b++) for (int i=0;i<T;i++) for (int j=0;j<T;j++){ double dd=std::abs(Ct[b*T*T+i*T+j]-Co[b*T*T+j*T+i]); mx=std::max(mx,dd); }
  printf("preatt halfbatch vs host-seq(bf16 rounded to half): %e\n", mx);
  // now vs host-seq WITHOUT half rounding (true bf16 inputs)
  double mx2=0; for (int b=0;b<NB;b++) for (int i=0;i<T;i++) for (int j=0;j<T;j++){ double dd=std::abs(Ct[b*T*T+i*T+j]-Co[b*T*T+j*T+i]); mx2=std::max(mx2,dd); }
  printf("(same, Ct already bf16-based; half rounding extra below)\n");
  // half rounding effect: compare Ct vs Ct computed from half-rounded inputs
  std::vector<float> Ch(NB*T*T, 0);
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++) for (int j=0;j<T;j++){ float a=0; for(int l=0;l<HS;l++) a+=(float)qh[b*T*HS+i*HS+l]*(float)kh[b*T*HS+j*HS+l]; Ch[b*T*T+i*T+j]=a; }
  double mx3=0; for(size_t i=0;i<Ct.size();i++) mx3=std::max(mx3,(double)std::abs(Ct[i]-Ch[i]));
  printf("bf16-input-seq vs half-input-seq: %e\n", mx3);
}
