#include <sycl/sycl.hpp>
#include <oneapi/math/blas.hpp>
#include <cstdio>
#include <vector>
#include <random>
int main(){
  sycl::queue q;
  using namespace oneapi::math;
  // verify corrected helper mapping on random data for all 4 transpose combos + NN, with T/HS sizes
  constexpr int m=32,n=48,k=16,NB=3;
  std::mt19937 rng(6); std::normal_distribution<float> d(0,1);
  for (int combo=0; combo<4; combo++) {
    bool tA = combo&2, tB = combo&1;
    int rowsA = tA?k:m, colsA = tA?m:k;   // row-major logical A storage (rowsA x colsA)
    int rowsB = tB?n:k, colsB = tB?k:n;
    std::vector<sycl::half> hA(NB*rowsA*colsA), hB(NB*rowsB*colsB);
    for (auto& x : hA) x = sycl::half(d(rng));
    for (auto& x : hB) x = sycl::half(d(rng));
    // host ref: Out(m x n) = op(A)*op(B)
    std::vector<float> Ct(NB*m*n, 0);
    for (int b=0;b<NB;b++) for (int i=0;i<m;i++) for (int j=0;j<n;j++){ float a=0; for(int l=0;l<k;l++){
      float av = tA ? (float)hA[b*rowsA*colsA + l*colsA + i] : (float)hA[b*rowsA*colsA + i*colsA + l];
      float bv = tB ? (float)hB[b*rowsB*colsB + j*colsB + l] : (float)hB[b*rowsB*colsB + l*colsB + j];
      a += av*bv; } Ct[b*m*n+i*n+j]=a; }
    sycl::half* Ah = sycl::malloc_device<sycl::half>(NB*rowsA*colsA, q);
    sycl::half* Bh = sycl::malloc_device<sycl::half>(NB*rowsB*colsB, q);
    float* O = sycl::malloc_device<float>(NB*m*n, q);
    q.memcpy(Ah, hA.data(), NB*rowsA*colsA*sizeof(sycl::half)).wait();
    q.memcpy(Bh, hB.data(), NB*rowsB*colsB*sizeof(sycl::half)).wait();
    q.memset(O, 0, NB*m*n*sizeof(float)).wait();
    transpose tu = tA ? transpose::trans : transpose::nontrans;
    transpose tv = tB ? transpose::trans : transpose::nontrans;
    int64_t ldu = tA ? m : k, ldv = tB ? k : n;
    blas::column_major::gemm_batch(q, tu, tv, m, n, k, 1.0f,
      Ah, ldu, (int64_t)rowsA*colsA, Bh, ldv, (int64_t)rowsB*colsB, 0.0f, O, m, (int64_t)m*n, NB).wait();
    std::vector<float> Co(NB*m*n);
    q.memcpy(Co.data(), O, NB*m*n*sizeof(float)).wait();
    // Co is col (m x n): element (i,j) at Co[b*m*n + j*m+i]
    double mx=0; for (int b=0;b<NB;b++) for (int i=0;i<m;i++) for (int j=0;j<n;j++){ double dd=std::abs(Ct[b*m*n+i*n+j]-Co[b*m*n+j*m+i]); mx=std::max(mx,dd); }
    printf("combo tA=%d tB=%d maxdiff=%e\n", (int)tA, (int)tB, mx);
    sycl::free(Ah,q); sycl::free(Bh,q); sycl::free(O,q);
  }
}
