#include <oneapi/math/blas.hpp>
#include <cstdio>
#include <vector>
#include <random>
#include <cmath>
int main(){
  sycl::queue q;
  using namespace oneapi::math;
  constexpr int B=2,T=8,NH=2,HS=8;
  int NB=B*NH;
  std::mt19937 rng(11); std::normal_distribution<float> d(0,1);
  std::vector<oneapi::math::bfloat16> hQ(NB*T*HS), hK(NB*T*HS), hV(NB*T*HS);
  for (auto& x : hQ) x = oneapi::math::bfloat16(d(rng));
  for (auto& x : hK) x = oneapi::math::bfloat16(d(rng));
  for (auto& x : hV) x = oneapi::math::bfloat16(d(rng));
  float scale = 1.f/sqrtf((float)HS);
  // host ref: preatt -> softmax -> vaccum, all fp32 from bf16 inputs, sequential k
  std::vector<float> pre(NB*T*T,0), att(NB*T*T,0), out(NB*T*HS,0);
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++) for (int j=0;j<T;j++){ float a=0; for(int l=0;l<HS;l++) a+=(float)hQ[b*T*HS+i*HS+l]*(float)hK[b*T*HS+j*HS+l]; pre[b*T*T+i*T+j]=a; }
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++){ float mx=-1e30; for(int j=0;j<=i;j++) mx=std::max(mx,pre[b*T*T+i*T+j]*scale); float s=0; for(int j=0;j<=i;j++) s+=expf(pre[b*T*T+i*T+j]*scale-mx); for(int j=0;j<T;j++) att[b*T*T+i*T+j]=(j<=i)?expf(pre[b*T*T+i*T+j]*scale-mx)/s:0; }
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++) for (int j=0;j<HS;j++){ float a=0; for(int l=0;l<T;l++) a+=att[b*T*T+i*T+l]*(float)hV[b*T*HS+l*HS+j]; out[b*T*HS+i*HS+j]=a; }
  // device path: half stage + batch gemm + fp32in softmax equivalent on host using device GEMM outputs
  std::vector<sycl::half> qh(NB*T*HS), kh(NB*T*HS), vh(NB*T*HS);
  std::vector<oneapi::math::bfloat16> hatt(NB*T*T);
  for (size_t i=0;i<qh.size();i++){ qh[i]=(sycl::half)(float)hQ[i]; kh[i]=(sycl::half)(float)hK[i]; vh[i]=(sycl::half)(float)hV[i]; }
  sycl::half* Qh = sycl::malloc_device<sycl::half>(NB*T*HS, q);
  sycl::half* Kh = sycl::malloc_device<sycl::half>(NB*T*HS, q);
  sycl::half* Vh = sycl::malloc_device<sycl::half>(NB*T*HS, q);
  float* P = sycl::malloc_device<float>(NB*T*T, q);
  float* V2 = sycl::malloc_device<float>(NB*T*HS, q);
  q.memcpy(Qh, qh.data(), NB*T*HS*sizeof(sycl::half)).wait();
  q.memcpy(Kh, kh.data(), NB*T*HS*sizeof(sycl::half)).wait();
  q.memcpy(Vh, vh.data(), NB*T*HS*sizeof(sycl::half)).wait();
  blas::column_major::gemm_batch(q, transpose::trans, transpose::nontrans, T, T, HS, 1.0f,
    Kh, HS, (int64_t)T*HS, Qh, HS, (int64_t)T*HS, 0.0f, P, T, (int64_t)T*T, NB).wait();
  std::vector<float> pdev(NB*T*T);
  q.memcpy(pdev.data(), P, NB*T*T*sizeof(float)).wait();
  double mx=0; for(size_t i=0;i<pre.size();i++) mx=std::max(mx,(double)std::abs(pre[i]-pdev[i]));
  printf("preatt dev-vs-host: %e\n", mx);
  // softmax on host from pdev, then vaccum compare with device vaccum
  std::vector<float> att2(NB*T*T,0);
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++){ float m2=-1e30; for(int j=0;j<=i;j++) m2=std::max(m2,pdev[b*T*T+i*T+j]*scale); float s=0; for(int j=0;j<=i;j++) s+=expf(pdev[b*T*T+i*T+j]*scale-m2); for(int j=0;j<T;j++) att2[b*T*T+i*T+j]=(j<=i)?expf(pdev[b*T*T+i*T+j]*scale-m2)/s:0; }
  double mxa=0; for(size_t i=0;i<att.size();i++) mxa=std::max(mxa,(double)std::abs(att[i]-att2[i]));
  printf("att dev-vs-host: %e\n", mxa);
  // device vaccum: need bf16 att -> half stage
  std::vector<oneapi::math::bfloat16> batt(NB*T*T);
  for (size_t i=0;i<batt.size();i++) batt[i] = oneapi::math::bfloat16(att2[i]);
  std::vector<sycl::half> ah(NB*T*T);
  for (size_t i=0;i<ah.size();i++) ah[i]=(sycl::half)(float)batt[i];
  sycl::half* Ah = sycl::malloc_device<sycl::half>(NB*T*T, q);
  q.memcpy(Ah, ah.data(), NB*T*T*sizeof(sycl::half)).wait();
  blas::column_major::gemm_batch(q, transpose::nontrans, transpose::nontrans, T, HS, T, 1.0f,
    Ah, T, (int64_t)T*T, Vh, HS, (int64_t)T*HS, 0.0f, V2, T, (int64_t)T*HS, NB).wait();
  std::vector<float> vdev(NB*T*HS);
  q.memcpy(vdev.data(), V2, NB*T*HS*sizeof(float)).wait();
  // host vaccum from bf16 att and bf16 V
  std::vector<float> vref(NB*T*HS,0);
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++) for (int j=0;j<HS;j++){ float a=0; for(int l=0;l<T;l++) a+=(float)batt[b*T*T+i*T+l]*(float)hV[b*T*HS+l*HS+j]; vref[b*T*HS+i*HS+j]=a; }
  double mxv=0; for(size_t i=0;i<vref.size();i++) mxv=std::max(mxv,(double)std::abs(vref[i]-vdev[i]));
  printf("vaccum dev-vs-host: %e\n", mxv);
}
