  floatX* qkvr = sycl::malloc_device<floatX>(n_qkvr, q);
  floatX* att = sycl::malloc_device<floatX>(n_att, q);
  floatX* out = sycl::malloc_device<floatX>(n_out, q);
  // tmp sized like train: max(B*T*Vp? here use att elems) — give plenty
  size_t tmpn = B*NH*T*T + 3*B*T*C + 1024;
  float* tmp = sycl::malloc_device<float>(tmpn, q);
  q.memcpy(inp, h_inp.data(), n_inp*sizeof(floatX)).wait();
  q.memset(qkvr, 0, n_qkvr*sizeof(floatX)).wait();
  q.memset(att, 0, n_att*sizeof(floatX)).wait();
  attention_forward(out, qkvr, att, inp, B, T, C, NH, q, tmp);
  q.wait();
  std::vector<floatX> h_out(n_out);
  q.memcpy(h_out.data(), out, n_out*sizeof(floatX)).wait();
  // host reference: permute, sequential preatt, softmax, vaccum, unpermute
  std::vector<float> qq(NB_omit,0);
  printf("device out[0..3]: %f %f %f %f\n", (float)h_out[0],(float)h_out[1],(float)h_out[2],(float)h_out[3]);
  // reference computed below with plain loops from h_inp
  int NB=B*NH;
  std::vector<float> Q(NB*T*HS),K(NB*T*HS),V(NB*T*HS);
  // permute: qo[idx] with idx=(b,nh,n,d): inp_idx=(b*N*3*NH*d)+(n*3*NH*d)+(nh*d)+d_
  for (int b=0;b<B;b++) for (int nh=0;nh<NH;nh++) for (int n=0;n<T;n++) for (int dd=0;dd<HS;dd++){
    size_t inp_idx = ((size_t)b*T*3*C)+(n*3*C)+(nh*HS)+dd;
    Q[((size_t)b*NH+nh)*T*HS+n*HS+dd]=(float)h_inp[inp_idx];
