  for (int b=0;b<NB;b++) for (int i=0;i<T;i++){ float m2=-1e30; for(int j=0;j<=i;j++) m2=std::max(m2,pre[b*T*T+i*T+j]*scale); float s=0; for(int j=0;j<=i;j++) s+=expf(pre[b*T*T+i*T+j]*scale-m2); for(int j=0;j<T;j++) at[b*T*T+i*T+j]=(j<=i)?expf(pre[b*T*T+i*T+j]*scale-m2)/s:0; }
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++) for (int j=0;j<HS;j++){ float a=0; for(int l=0;l<T;l++) a+=at[b*T*T+i*T+l]*V[b*T*HS+l*HS+j]; va[b*T*HS+i*HS+j]=a; }
  // unpermute: out[b,n,nh,d] = va[(b,nh,n,d)]
  double mx=0; for (int b=0;b<B;b++) for (int n=0;n<T;n++) for (int nh=0;nh<NH;nh++) for (int dd=0;dd<HS;dd++){
    float ref = va[((size_t)b*NH+nh)*T*HS+n*HS+dd];
    float got = (float)h_out[((size_t)b*T*C)+n*C+nh*HS+dd];
    mx=std::max(mx,(double)std::abs(ref-got));
  }
  printf("attention_forward maxdiff vs host: %e\n", mx);
}
