  // check: does oneMath gemm_batch preserve in-order semantics wrt preceding kernels writing ha/hb?
  constexpr int N = 1024;
  std::vector<floatX> h(N, (floatX)1.0f);
  floatX* S = sycl::malloc_device<floatX>(N, q);
  q.memcpy(S, h.data(), N*sizeof(floatX)).wait();
  sycl::half* H = sycl::malloc_device<sycl::half>(N, q);
  // fire converts + dependent kernels WITHOUT wait, then read
  for (int iter=0; iter<3; iter++) {
    bf16_to_half_convert(H, S, N, q);
    // scale H by iter via kernel
    q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id){ H[id[0]] = (sycl::half)((float)H[id[0]] * (iter+1)); });
  }
  q.wait();
  std::vector<sycl::half> ho(N);
  q.memcpy(ho.data(), H, N*sizeof(sycl::half)).wait();
  printf("H[0]=%f (expect %f)\n", (float)ho[0], 1.0f*1*2*3);
}
