  std::vector<oneapi::math::bfloat16> hQ(NB*T*HS), hK(NB*T*HS);
  for (auto& x : hQ) x = oneapi::math::bfloat16(d(rng));
  for (auto& x : hK) x = oneapi::math::bfloat16(d(rng));
  oneapi::math::bfloat16* Q = sycl::malloc_device<oneapi::math::bfloat16>(NB*T*HS, q);
  oneapi::math::bfloat16* K = sycl::malloc_device<oneapi::math::bfloat16>(NB*T*HS, q);
  q.memcpy(Q, hQ.data(), NB*T*HS*sizeof(oneapi::math::bfloat16)).wait();
  q.memcpy(K, hK.data(), NB*T*HS*sizeof(oneapi::math::bfloat16)).wait();
  // route A: loop of bf16 gemms -> tmpA
  float* A = sycl::malloc_device<float>(NB*T*T, q);
  for (int b=0;b<NB;b++)
    blas::column_major::gemm(q, transpose::trans, transpose::nontrans, T, T, HS, 1.0f,
      K+b*T*HS, HS, Q+b*T*HS, HS, 0.0f, A+b*T*T, T).wait();
  // route B: half stage + strided batch -> tmpB
  sycl::half* Qh = sycl::malloc_device<sycl::half>(NB*T*HS, q);
  sycl::half* Kh = sycl::malloc_device<sycl::half>(NB*T*HS, q);
  float* Bf = sycl::malloc_device<float>(NB*T*T, q);
  q.parallel_for(sycl::range<1>(NB*T*HS), [=](sycl::id<1> id){ Qh[id[0]] = (sycl::half)(float)Q[id[0]]; });
  q.parallel_for(sycl::range<1>(NB*T*HS), [=](sycl::id<1> id){ Kh[id[0]] = (sycl::half)(float)K[id[0]]; });
  blas::column_major::gemm_batch(q, transpose::trans, transpose::nontrans, T, T, HS, 1.0f,
    Kh, HS, (int64_t)T*HS, Qh, HS, (int64_t)T*HS, 0.0f, Bf, T, (int64_t)T*T, NB).wait();
  std::vector<float> a(NB*T*T), b(NB*T*T);
  q.memcpy(a.data(), A, NB*T*T*sizeof(float)).wait();
  q.memcpy(b.data(), Bf, NB*T*T*sizeof(float)).wait();
  double mx=0,mean=0; for(size_t i=0;i<a.size();i++){ double dd=std::abs(a[i]-b[i]); mx=std::max(mx,dd); mean+=dd; }
  printf("preatt fp32: maxdiff=%e meandiff=%e (scale ~ %.1f)\n", mx, mean/a.size(), std::abs(a[0]));
  // now softmax both (host) and compare att
  float scale = 1.f/sqrtf((float)HS);
  auto softmax = [&](std::vector<float>& p){ std::vector<float> o(p.size()); for(int b2=0;b2<NB;b2++) for(int i=0;i<T;i++){ float m2=-1e30; for(int j=0;j<=i;j++) m2=std::max(m2,p[b2*T*T+i*T+j]*scale); float s=0; for(int j=0;j<=i;j++) s+=expf(p[b2*T*T+i*T+j]*scale-m2); for(int j=0;j<T;j++) o[b2*T*T+i*T+j]=(j<=i)?expf(p[b2*T*T+i*T+j]*scale-m2)/s:0; } return o; };
  std::vector<float> aa=softmax(a), bb=softmax(b);
  double mx2=0; for(size_t i=0;i<aa.size();i++) mx2=std::max(mx2,(double)std::abs(aa[i]-bb[i]));
  printf("att maxdiff=%e\n", mx2);
}
