#include <sycl/sycl.hpp>
#include <oneapi/math/blas.hpp>
#include <cstdio>
#include <vector>
#include <random>
// vaccum: bf16-loop (A=att bf16, B=V bf16) vs half-batch (A=att bf16->half, B=V bf16->half)
int main(){
  sycl::queue q(sycl::default_selector_v, sycl::property::queue::in_order{});
  using namespace oneapi::math;
  constexpr int T=64,HS=64,NB=48;
  std::mt19937 rng(62); std::normal_distribution<float> d(0,1);
  // att-like: softmax outputs in [0,1]; V-like: N(0,1)
  std::vector<oneapi::math::bfloat16> hA(NB*T*T), hV(NB*T*HS);
  for (auto& x : hA) x = oneapi::math::bfloat16(std::abs(d(rng))/8.0f);
  for (auto& x : hV) x = oneapi::math::bfloat16(d(rng));
  // normalize rows of hA to sum 1 (softmax-like)
  for (int b=0;b<NB;b++) for (int i=0;i<T;i++){ float s=0; for(int j=0;j<T;j++) s+=(float)hA[b*T*T+i*T+j]; for(int j=0;j<T;j++) hA[b*T*T+i*T+j]=oneapi::math::bfloat16((float)hA[b*T*T+i*T+j]/s); }
  oneapi::math::bfloat16* A = sycl::malloc_device<oneapi::math::bfloat16>(NB*T*T, q);
  oneapi::math::bfloat16* V = sycl::malloc_device<oneapi::math::bfloat16>(NB*T*HS, q);
  q.memcpy(A, hA.data(), NB*T*T*sizeof(oneapi::math::bfloat16)).wait();
  q.memcpy(V, hV.data(), NB*T*HS*sizeof(oneapi::math::bfloat16)).wait();
  float* O1 = sycl::malloc_device<float>(NB*T*HS, q);
  // route A: loop bf16 gemm, mapping Out(TxHS)=A(TxT)*V(TxHS): C_col? use swapped: gemm(n=HS,m=T,k=T, B=V, A)
  for (int b=0;b<NB;b++)
