#include <sycl/sycl.hpp>
#include <cstdio>
#include <vector>
#include <random>
sycl::queue sycl_queue;
#include "llmc/sycl_common.h"
#include "llmc/sycl_utils.hpp"
// inline only softmax_forward (no attention include -> no matmul include)
inline void my_softmax_forward(floatX* out, float inv_temperature, const floatX* inp, int NT, int T, sycl::queue& qq) {
    sycl::queue& q = qq;
    size_t rows = (size_t)NT * T;
    if (rows == 0 || T <= 0) { return; }
    constexpr size_t WG = 128;
    const float flt_max = 340282346638528859811704183484516925440.0f;
    q.parallel_for(sycl::nd_range<1>(rows * WG, WG), [=](sycl::nd_item<1> it) {
        size_t idx = it.get_group(0);
        size_t lid = it.get_local_id(0);
        sycl::group<1> g = it.get_group();
        size_t own_pos = idx % (size_t)T;
        const floatX* x = inp + idx * (size_t)T;
        floatX* o = out + idx * (size_t)T;
        size_t n = own_pos + 1;
        float maxval = -flt_max;
        float sumval = 0.0f;
        for (size_t i = lid; i < n; i += WG) {
            float r = (float)x[i];
            float old = maxval;
            maxval = fmaxf(maxval, r);
            sumval *= sycl::exp(inv_temperature * (old - maxval));
            sumval += sycl::exp(inv_temperature * (r - maxval));
        }
        float gmax = sycl::reduce_over_group(g, maxval, sycl::maximum<float>());
        sumval *= sycl::exp(inv_temperature * (maxval - gmax));
        float gsum = sycl::reduce_over_group(g, sumval, sycl::plus<float>());
        float norm = 1.0f / gsum;
        for (size_t i = lid; i < n; i += WG) {
            float ev = sycl::exp(inv_temperature * ((float)x[i] - gmax));
            o[i] = (floatX)(ev * norm);
        }
    });
}
int main(){
  sycl_queue = sycl::queue(sycl::default_selector_v, sycl::property::queue::in_order{});
  sycl::queue& q = sycl_queue;
  constexpr int NT=48,T=64;
  std::mt19937 rng(71); std::normal_distribution<float> d(0,3);
  std::vector<floatX> hb(NT*T);
  for (auto& x : hb) x = (floatX)d(rng);
  floatX* bdin = sycl::malloc_device<floatX>(NT*T, q);
  floatX* o1 = sycl::malloc_device<floatX>(NT*T, q);
  q.memcpy(bdin, hb.data(), NT*T*sizeof(floatX)).wait();
  my_softmax_forward(o1, 0.125f, bdin, NT, T, q);
  q.wait();
  printf("ok\n");
}
