#include <sycl/sycl.hpp>
#include <cstdio>
#include <vector>
sycl::queue sycl_queue;
#include "llmc/sycl_common.h"
#include "llmc/sycl_utils.hpp"
int main(){
  sycl_queue = sycl::queue(sycl::default_selector_v, sycl::property::queue::in_order{});
  sycl::queue& q = sycl_queue;
  // measure: separate convert kernel (range<1> with i%OC) vs fused-2D epilogue on CPU? CPU timing meaningless.
  // Instead verify the 2D epilogue gives BIT-IDENTICAL results to the 1D one (must, same order/rounding).
  constexpr int BT=256, OC=768, C=768;
  std::vector<float> tmp(BT*OC);
  for (size_t i=0;i<tmp.size();i++) tmp[i] = (float)(i%100)*0.01f - 0.5f;
  std::vector<floatX> bias(OC, (floatX)0.1f);
  float* dtmp = sycl::malloc_device<float>(BT*OC, q);
  floatX* db = sycl::malloc_device<floatX>(OC, q);
  floatX* o1 = sycl::malloc_device<floatX>(BT*OC, q);
  floatX* o2 = sycl::malloc_device<floatX>(BT*OC, q);
  q.memcpy(dtmp, tmp.data(), BT*OC*sizeof(float)).wait();
  q.memcpy(db, bias.data(), OC*sizeof(floatX)).wait();
  size_t N = (size_t)OC*BT;
  // 1D (old)
  q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id) {
    size_t i = id[0]; size_t oc = i % (size_t)OC;
    float v = dtmp[i] + (float)db[oc];
    o1[i] = (floatX)v;
  });
  q.wait();
  // 2D (new)
  size_t nBT=BT, nOC=OC;
  q.parallel_for(sycl::range<2>(nBT, nOC), [=](sycl::id<2> id) {
    size_t r=id[0], oc=id[1]; size_t i=r*nOC+oc;
    float v = dtmp[i] + (float)db[oc];
    o2[i] = (floatX)v;
  });
  q.wait();
  std::vector<floatX> r1(BT*OC), r2(BT*OC);
  q.memcpy(r1.data(), o1, BT*OC*sizeof(floatX)).wait();
  q.memcpy(r2.data(), o2, BT*OC*sizeof(floatX)).wait();
  int diff=0; for (int i=0;i<BT*OC;i++) if ((float)r1[i]!=(float)r2[i]) diff++;
  printf("1D vs 2D epilogue diffs: %d\n", diff);
}
