// Fused residual + layernorm with fp32 matmul input:
//   residual[row*C+c] = (floatX)(inp1 + (gemm_fp32 + bias))
//   normed = layernorm(residual)
// Reads the column-major (C x N) fp32 GEMM output as row-major (N x C).
// Same arithmetic (same order, one rounding per store) as running the
// convert, residual and layernorm kernels separately.
inline void fused_residual_forward5_fp32in(floatX* residual, floatX* normed, float* mean, float* rstd,
                             const floatX* inp1, const float* gemm_fp32, const floatX* bias,
                             const floatX* weight, const floatX* ln_bias,
                             int N, int C, sycl::queue& q) {
    NVTX_RANGE_FN();
    if (N <= 0) return;
    bool has_bias = (bias != nullptr);
    size_t wg = 256;
    size_t nC = (size_t)C;
    q.parallel_for(sycl::nd_range<1>((size_t)N * wg, wg), [=](sycl::nd_item<1> it) {
        size_t row = it.get_group(0);
        size_t lid = it.get_local_id(0);
        sycl::group<1> g = it.get_group();
        const floatX* x1 = inp1 + row * nC;
        const float* x2 = gemm_fp32 + row * nC;
        floatX* res = residual + row * nC;
        // pass 1: residual store (fused convert+bias+add) + mean
        float sum = 0.0f;
        for (size_t c = lid; c < nC; c += wg) {
            float v = x2[c];
            if (has_bias) { v += (float)bias[c]; }
            float r = (float)x1[c] + v;
            res[c] = (floatX)r;
            sum += r;
        }
        float total = sycl::reduce_over_group(g, sum, sycl::plus<float>());
        float m = total / (float)C;
        // pass 2: variance over the just-written residual row
        float vsum = 0.0f;
        for (size_t c = lid; c < nC; c += wg) {
            float d = (float)res[c] - m;
            vsum += d * d;
        }
        float vtotal = sycl::reduce_over_group(g, vsum, sycl::plus<float>());
        float s = sycl::rsqrt(vtotal / (float)C + 1e-5f);
        if (lid == 0) {
            if (mean != nullptr) { mean[row] = m; }
            if (rstd != nullptr) { rstd[row] = s; }
        }
        floatX* o = normed + row * nC;
        for (size_t c = lid; c < nC; c += wg) {
            float nrm = s * ((float)res[c] - m);
            o[c] = (floatX)(nrm * (float)weight[c] + (float)ln_bias[c]);
        }
    });
}

