#include <sycl/sycl.hpp>
#include <cstdio>
#include <vector>
sycl::queue sycl_queue;
#include "llmc/sycl_common.h"
#include "llmc/sycl_utils.hpp"
int main(){
  sycl_queue = sycl::queue(sycl::default_selector_v, sycl::property::queue::in_order{});
  sycl::queue& q = sycl_queue;
  // does the x128 vectorized residual do the SAME rounding as scalar? packed_out[k]=(floatX)((float)a+(float)b)
  // vs scalar out[i]=(floatX)((float)a+(float)b). Should be identical... unless load128cs/store128 on CPU misbehave (unaligned? reinterpret cast of vec<int,4> requires 16B alignment; idx may be unaligned for rem path — handled by rem branch).
  // Test residual_forward vs manual on LARGER random data
  constexpr int N=4096;
  std::vector<floatX> ha(N), hb(N);
  for (int i=0;i<N;i++){ ha[i]=(floatX)((i%997)*0.013f-6.0f); hb[i]=(floatX)((i%613)*0.017f-5.0f); }
  floatX *a = sycl::malloc_device<floatX>(N, q);
  floatX *b = sycl::malloc_device<floatX>(N, q);
  floatX *o1 = sycl::malloc_device<floatX>(N, q);
  floatX *o2 = sycl::malloc_device<floatX>(N, q);
  q.memcpy(a, ha.data(), N*sizeof(floatX)).wait();
  q.memcpy(b, hb.data(), N*sizeof(floatX)).wait();
  // manual in C++ (host): ref
  std::vector<float> ref(N);
  for (int i=0;i<N;i++) ref[i]=(float)(floatX)((float)ha[i]+(float)hb[i]);
  residual_forward(o1, a, b, N, q);
  q.wait();
  // scalar kernel
  q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id){ size_t i=id[0]; o2[i]=(floatX)((float)a[i]+(float)b[i]); }).wait();
  std::vector<floatX> r1(N), r2(N);
  q.memcpy(r1.data(), o1, N*sizeof(floatX)).wait();
  q.memcpy(r2.data(), o2, N*sizeof(floatX)).wait();
  int d1=0,d2=0; for(int i=0;i<N;i++){ if((float)r1[i]!=ref[i])d1++; if((float)r2[i]!=ref[i])d2++; }
  printf("vec-vs-host diffs=%d scalar-vs-host diffs=%d\n", d1, d2);
  int d3=0; for(int i=0;i<N;i++) if((float)r1[i]!=(float)r2[i])d3++;
  printf("vec-vs-scalar diffs=%d\n", d3);
}
